// TestKbdDlg.cpp : файл реализации//#include "stdafx.h"#include "TestKbd.h"#include "TestKbdDlg.h"#define __MAIN_FILE__#include <KeybCOM.h>#undef __MAIN_FILE__#ifdef _DEBUG#define new DEBUG_NEW#endif// диалоговое окно CTestKbdDlgCTestKbdDlg::CTestKbdDlg(CWnd* pParent /*=NULL*/)	: CDialog(CTestKbdDlg::IDD, pParent){	m_hIcon = AfxGetApp()->LoadIcon(IDR_MAINFRAME);}void CTestKbdDlg::DoDataExchange(CDataExchange* pDX){	CDialog::DoDataExchange(pDX);}BEGIN_MESSAGE_MAP(CTestKbdDlg, CDialog)	ON_WM_PAINT()	ON_WM_QUERYDRAGICON()	//}}AFX_MSG_MAPEND_MESSAGE_MAP()// обработчики сообщений CTestKbdDlgBOOL CTestKbdDlg::OnInitDialog(){	CDialog::OnInitDialog();	SetIcon(m_hIcon, TRUE);	SetIcon(m_hIcon, FALSE);	return TRUE;}void CTestKbdDlg::OnPaint(){	if (IsIconic())	{		CPaintDC dc(this); // контекст устройства для рисования		SendMessage(WM_ICONERASEBKGND, reinterpret_cast<WPARAM>(dc.GetSafeHdc()), 0);		int cxIcon = GetSystemMetrics(SM_CXICON);		int cyIcon = GetSystemMetrics(SM_CYICON);		CRect rect;		GetClientRect(&rect);		int x = (rect.Width() - cxIcon + 1) / 2;		int y = (rect.Height() - cyIcon + 1) / 2;		dc.DrawIcon(x, y, m_hIcon);	}	else	{		CDialog::OnPaint();	}}HCURSOR CTestKbdDlg::OnQueryDragIcon(){	return static_cast<HCURSOR>(m_hIcon);}void CTestKbdDlg::OnOK(){	BOOL bResult = StartKeyboard ();}BOOL CTestKbdDlg::StartKeyboard (){	STARTUPINFO si={0};	si.cb = sizeof(si);	PROCESS_INFORMATION pi={0};	char szCmdLine[256];	lstrcpy( szCmdLine, "keybusb.exe" );/*	if ( lstrcmp( KYokoPipeClient::ms_szServer, "." ) )	{		lstrcat( szCmdLine, " -s" );		lstrcat( szCmdLine, KYokoPipeClient::ms_szServer);	}*/	BOOL bResult = CreateProcess (NULL, szCmdLine, NULL, NULL, FALSE, 0, NULL, NULL, &si, &pi);	return bResult;}